G=load(); print(sorted(G))

def f(inp):
    H=len(inp); W=len(inp[0])
    def issep(v): return v==8
    sepR=[r for r in range(H) if all(issep(x) for x in inp[r])]
    # column separators: columns where every non-sep-row has 8
    def isSepCol(c):
        for r in range(H):
            if inp[r][c]!=8: return False
        return True
    sepC=[c for c in range(W) if isSepCol(c)]
    segs=lambda n:[x for i,x in enumerate(range(0,n)) if x in sepR and i in segs(n)]
    def blocks(ax):
        b=[];s=0
        for x in ax+[n]:
            if s<x: b.append((s,x))
            s=x+1
        return b
    def key(r,c):
        rb=sum(1 for x in range(r+1,H) if x not in sepR)
        cb=sum(1 for x in range(c+1,W) if x not in sepC)
        return (-rb,-cb)
    blocks_r=blocks(H-1); blocks_c=blocks(W-1)
    out=[row[:] for row in inp]
    for r in range(H):
        if r in sepR: continue
        bi=r; _=None
        for i,(a,b) in enumerate(blocks_r):
            if a<=r<b: bi=i
        for c in range(W):
            if c in sepC: continue
            for j,(a,b) in enumerate(blocks_c):
                if a<=c<b: bj=j
                break
        br,bc=key(r,c)
        col=inp[r][c]
        if col!=0 and col!=8:
            for di in range(3):
                for dj in range(3):
                    rr,cc=r-di+c-bi*0, c-dj
                    rr=r-di+(di)*(-br)
                    # simpler: recompute using block bounds
                    out[rb+di][cb+dj]=col
    return out

