def f(g):
    H,W=len(g),len(g[0])
    sepR=[r for r in range(H) if all(v==8 for v in g[r])]
    sepC=[c for c in range(W) if all(g[r][c]==8 for r in range(H))]
    def blocks(seps,n):
        bs=[];s=-1
        for x in seps+[n]:
            if s<x: bs.append((s+1,x-1)); s=x
        return bs
    rb=blocks(sepR,H); cb=blocks(sepC,W)
    out=[[g[r][c] for c in range(W)] for r in range(H)]
    # vertical: per colblock, per color, fill between min and max band containing that color
    for c0,c1 in cb:
        bands_bycolor={}
        for r in range(H):
            vv={g[r][c] for c in range(c0,c1+1) if g[r][c] not in (0,8)}
            for v in vv:
                bi=next(i for i,(a,b) in enumerate(rb) if a<=r<=b)
                bands_bycolor.setdefault(v,set()).add(bi)
        for v,bs in bands_bycolor.items():
            mn,mx=min(bs),max(bs)
            for bi in range(mn,mx+1):
                ra,rb_=rb[bi]
                for r in range(ra,rb_+1):
                    for c in range(c0,c1+1):
                        if out[r][c]==8: out[r][c]=v
    # horizontal: per band with marks
    for r0,r1 in rb:
        marks=[]
        for r in range(r0,r1+1):
            for c in range(W):
                if g[r][c] not in (0,8): marks.append((r,c,g[r][c]))
        if not marks: continue
        L=min(m[1] for m in marks); R=max(m[1] for m in marks)
        inter=[b for b in cb if b[0]>L and b[1]<R]
        v=set(m[2] for m in marks)
        for b in inter:
            for r in range(r0,r1+1):
                for c in range(b[0],b[1]+1):
                    out[r][c]=next(iter(v))
        n=len(inter)
        if n>=3:
            t=inter[n-3]
            for r in range(r0,r1+1):
                for c in range(t[0],t[1]+1):
                    out[r][c]=6
    return out

