    sr=[r for r in range(H) if all(v==8 for v in g[r])]
    sc=[c for c in range(W) if all(g[r][c]==8 for r in range(H))]
    def runs(seps,n):
        rs=[];prev=-1
        for x in seps+[n]:
            if x>prev+1: rs.append((prev+1,x-1))
            prev=x
        return rs
    rb=runs(sr,H); cb=runs(sc,W)
    out=[[g[r][c] for c in range(W)] for r in range(H)]
    # vertical: each mark fills its own band (the band containing it) fully in its column-block
    for c0,c1 in cb:
        for r in range(H):
            if any(c0<=cc<=c1 and g[r][cc]!=0 and g[r][cc]!=8 for cc in range(c0,c1+1)):
                bi=next(i for i,(a,b) in enumerate(rb) if a<=r<=b)
                for rr in range(max(a,b),b+1):
                    for cc in range(c0,c1+1):
                        out[rr][cc]=g[r][cc]
    # horizontal: per band, fill blocks from first to last marked column; interior special block gets 6
    for r0,r1 in rb:
        marks=[]
        for r in range(r0,r1+1):
            for c in range(W):
                if g[r][c] not in (0,8): marks.append((c,g[r][c]))
        if not marks: continue
        cs=[m[0] for m in marks]
        L,R=min(cs),max(cs)
        inter=[b for b in cb if b[0]>L and b[1]<R]
        col=set()
        for r in range(r0,r1+1):
            for c in range(L,R+1):
                if g[r][c] not in (0,8): col.add(g[r][c])
        if len(col)!=1: return None  # unknown multi-color
        v=next(iter(col))
        for b in range(rb.index(next(bb for bb in rb if bb[0]<=L)) ,rb.index(next(bb for bb in rb if bb[1]>=R))+1):
            pass
        # fill blocks from first marked block to last marked block
        mbk_first=next(j for j,(a,b) in enumerate(cb) if b>=L)
        mbk_last=next(j for j,(a,b) in enumerate(cb) if a<=R)
        for j in range(mbk_first,mbk_last+1):
            for rr in range(r0,r1+1):
                for cc in range(cb[j][0],cb[j][1]+1):
                    out[rr][cc]=v
        n_blocks_between=mbk_last-mbk_first-1
        if n_blocks_between>=3:
            sp=cb[mbk_first+n_blocks_between-2]
            for rr in range(r0,r1+1):
                for cc in range(sp[0],sp[1]+1):
                    out[rr][cc]=6
    return out

