    cb=[];prev=-1
    for x in sc+[W]:
        if x>prev+1: cb.append((prev+1,x-1)); prev=x
    res=[[0]*W for _ in range(H)]
    # markers with band/index info
    mks=[]
    for r in range(H):
        for c in range(W):
            v=g[r][c]
            if v not in (0,8):
                bi=next(i for i,(a,b) in enumerate(rb) if a<=r<=b)
                bj=next(j for j,(a,b) in enumerate(cb) if a<=c<=y for y in [b])
                mks.append((bi,bj,c,v,r))
    # last marked band
    last=max(bi for _,_,_,_,r in mks)
    # markers grouped by band
    byband={}
    for bi,bj,c,v,r in mks:
        byband.setdefault(bi,{}).setdefault(bj,[]).append((c,v))
    for bi,(a,b) in enumerate(rb):
        marks=byband.get(bi,{})
