            cols=sorted({c for js in marks.values() for c in js})
            vals={v for js in marks.values() for c,v in js}
            c0=min(cols); c1=max(cols)
            for r in range(a,b+1):
                for c in range(c0,c1+1):
                    vv=next(v for c_,v in marks.values() if c_==c)
                    # conflict: any marker above in same column with different color?
