                                conf=True
                    res[r][c]=6 if conf else vv
        else:
            # inheritance: nearest marker above in same colblock
            for r in range(a,b+1):
                for bj,(x,y) in enumerate(cb):
                    if x<=0<=y: pass
                    # find nearest earlier band with marker in this block
                    best=None
                    for prevb in range(bi):
                        for pj,(px,py) in enumerate(cb):
                            if pj==bj and any(v not in (0,8) for _,v in byband.get(prevb,{}).get(pj,[]) ):
                                cands=[v for (_,v) in byband[prevb].get(pj,[]) ]
                                if cands:
                                    best=(prevb,cands[0])
                    if best:
                        pb,pv=best
                        res[r][x:py+1]=[pv]* (py-x+1)
    return res

