import numpy as np, json, glob, os, re
from collections import Counter, deque
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    G={}
    for p in glob.glob(d+'/../../sessions/*.jsonl'):
        t=open(p,encoding='utf8',errors='ignore').read().replace('\\n','\n')
        for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
            k,h,w=m[1],int(m[2]),int(m[3])
            rows=[r.split() for r in t[m.end():].split('\n')[:h]]
            if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
                G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
def f(g):
    g=np.array(g); h,w=g.shape
    comp=[]; seen=np.zeros_like(g,bool)
    for i in range(h):
        for j in range(w):
            if not seen[i,j]:
                v=g[i,j]; q=deque([(i,j)]); seen[i,j]=True; cells=[]
                while q:
                    y,x=q.popleft(); cells.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<w and not seen[ny,nx] and g[ny,nx]==v:
                            seen[ny,nx]=True; q.append((ny,nx))
                comp.append((v,cells))
    res=g.copy()
    for v,cells in comp:
        if len(cells)==1:
            y,x=cells[0]
            nb=[g[a,b] for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)) if 0<=(y+dy)<h and 0<=(x+dx)<w]
            cnt=Counter(nb); best,cntv=cnt.most_common(1)[0]
            # tie-break: prefer neighbors that belong to larger components / most frequent globally
            res[y,x]=best
    return res.tolist()
