def try_comp_rule(g, tiebreak='minority', bg_only=False):
    bg,out=comps(g); o=g.copy()
    for c,comp in out:
        cs=Counter(g[y,x] for y,x in comp)
        if bg_only and c==bg: continue
        m=max(cs.values()); cand=[v for v,vv in cs.items() if vv==m]
        if len(cand)==1: rep=cand[0]; keep=True
        else:
            n=len(comp)
            if tiebreak=='keep': rep=c; keep=False
            elif tiebreak=='majority': cand.sort(reverse=True); rep=cand[0]; keep=True
            else: rep=min(cand)
        if keep:
            for y,x in comp: o[y,x]=rep
    return o.tolist()
